"""
Run this once to write the remaining persistence files directly --
the product repository, the fixed /products route, and the updated
products.html template. Delete this file afterwards if you like.
"""

repo_content = 'from app.database.database import SessionLocal\nfrom app.database.models import ProductRecord\n\n\nclass ProductRepository:\n    """\n    Handles saving opportunity scan results to the database and\n    reading them back. Manages its own DB session per call, since\n    this is used from services (BrandScanService) rather than routes\n    that have FastAPI\'s Depends(get_db) available.\n    """\n\n    @staticmethod\n    def save_opportunity(product_dict: dict, report_dict: dict, brand_query: str):\n        db = SessionLocal()\n\n        try:\n            record = ProductRecord(\n                asin=product_dict.get("asin") or "",\n                title=product_dict.get("title") or "",\n                brand=product_dict.get("brand") or "",\n                category=product_dict.get("category") or "",\n                brand_query=brand_query,\n                buy_box_now=product_dict.get("buy_box_now") or 0.0,\n                buy_box_90d=product_dict.get("buy_box_90d") or 0.0,\n                best_source_marketplace=product_dict.get("best_source_marketplace") or "",\n                best_source_cost_gbp=product_dict.get("best_source_cost_gbp") or 0.0,\n                fba_fee=product_dict.get("fba_fee") or 0.0,\n                referral_fee=product_dict.get("referral_fee") or 0.0,\n                profit=product_dict.get("profit") or 0.0,\n                roi=product_dict.get("roi") or 0.0,\n                score=report_dict.get("score") or 0,\n                confidence=report_dict.get("confidence") or 0,\n                recommendation=report_dict.get("recommendation") or "",\n            )\n            db.add(record)\n            db.commit()\n\n        except Exception as exc:\n            db.rollback()\n            # A failed save shouldn\'t break the scan itself -- just log it.\n            print(f"Failed to save product record for {product_dict.get(\'asin\')}: {exc}")\n\n        finally:\n            db.close()\n\n    @staticmethod\n    def list_latest(limit: int = 200):\n        """\n        Returns the most recently scanned record per ASIN (not every\n        historical row) -- most recently scanned first.\n        """\n        db = SessionLocal()\n\n        try:\n            recent = (\n                db.query(ProductRecord)\n                .order_by(ProductRecord.scanned_at.desc())\n                .limit(limit * 5)  # generous overfetch before de-duplicating\n                .all()\n            )\n\n            seen = set()\n            latest = []\n\n            for record in recent:\n                if record.asin in seen:\n                    continue\n\n                seen.add(record.asin)\n                latest.append(record)\n\n                if len(latest) >= limit:\n                    break\n\n            return latest\n\n        finally:\n            db.close()\n'
route_content = 'from fastapi import APIRouter, Request\nfrom fastapi.templating import Jinja2Templates\n\nfrom app.services.product_repository import ProductRepository\n\nrouter = APIRouter()\n\ntemplates = Jinja2Templates(directory="app/templates")\n\n\n@router.get("/products")\ndef products(request: Request):\n    records = ProductRepository.list_latest(limit=200)\n\n    return templates.TemplateResponse(\n        request=request,\n        name="products.html",\n        context={\n            "request": request,\n            "products": records,\n        }\n    )\n'
template_content = '{% extends "base.html" %}\n\n{% block title %}Products - Atlas{% endblock %}\n\n{% block content %}\n\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h4 class="mb-0">Products (latest scan per ASIN)</h4>\n    <a href="/discovery" class="btn btn-dark btn-sm">\n        <i class="bi bi-search"></i> Run a new scan\n    </a>\n</div>\n\n{% if products %}\n\n<div class="card metric p-3">\n    <div class="table-responsive">\n        <table class="table table-hover align-middle">\n            <thead>\n                <tr>\n                    <th>Product</th>\n                    <th>Found via</th>\n                    <th>Best Source</th>\n                    <th class="text-end">Source Cost</th>\n                    <th class="text-end">UK Price</th>\n                    <th class="text-end">Profit</th>\n                    <th class="text-end">ROI</th>\n                    <th>Score</th>\n                    <th>Recommendation</th>\n                    <th>Last Scanned</th>\n                </tr>\n            </thead>\n            <tbody>\n                {% for p in products %}\n                <tr>\n                    <td style="max-width:280px;">\n                        <div class="fw-semibold small">{{ p.title[:70] }}{% if p.title|length > 70 %}...{% endif %}</div>\n                        <div class="text-muted small">{{ p.asin }} &middot; {{ p.brand }}</div>\n                    </td>\n                    <td>{{ p.brand_query }}</td>\n                    <td>{{ p.best_source_marketplace }}</td>\n                    <td class="text-end">&pound;{{ "%.2f"|format(p.best_source_cost_gbp) }}</td>\n                    <td class="text-end">&pound;{{ "%.2f"|format(p.buy_box_now) }}</td>\n                    <td class="text-end {{ \'text-success\' if p.profit > 0 else \'text-danger\' }}">\n                        &pound;{{ "%.2f"|format(p.profit) }}\n                    </td>\n                    <td class="text-end {{ \'text-success\' if p.roi > 0 else \'text-danger\' }}">\n                        {{ "%.1f"|format(p.roi) }}%\n                    </td>\n                    <td>{{ p.score }}</td>\n                    <td>\n                        {% if p.recommendation == "BUY" %}\n                            <span class="badge bg-success">BUY</span>\n                        {% elif p.recommendation == "REVIEW" %}\n                            <span class="badge bg-warning text-dark">REVIEW</span>\n                        {% else %}\n                            <span class="badge bg-secondary">IGNORE</span>\n                        {% endif %}\n                    </td>\n                    <td class="small text-muted">{{ p.scanned_at.strftime("%Y-%m-%d %H:%M") if p.scanned_at else "" }}</td>\n                </tr>\n                {% endfor %}\n            </tbody>\n        </table>\n    </div>\n</div>\n\n{% else %}\n\n<div class="alert alert-info">\n    <h5>No products saved yet</h5>\n    <p class="mb-0">Run a scan on the <a href="/discovery">Discovery</a> page -- every opportunity found gets saved here automatically.</p>\n</div>\n\n{% endif %}\n\n{% endblock %}\n'

with open("app/services/product_repository.py", "w", encoding="utf-8") as f:
    f.write(repo_content)

with open("app/routes/products.py", "w", encoding="utf-8") as f:
    f.write(route_content)

with open("app/templates/products.html", "w", encoding="utf-8") as f:
    f.write(template_content)

print("Done -- product_repository.py, routes/products.py, and products.html written.")